const C={sky:'#0c222c',far:'#13353a',mid:'#184341',ink:'#0a2329',leaf:'#20554a',moss:'#83b584',light:'#c5ead0',cyan:'#8ef1df',gold:'#eac480'};
const noise=(n)=>{let v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)};
function rect(c,x,y,w,h,col){c.fillStyle=col;c.fillRect(Math.round(x),Math.round(y),w,h)}
function poly(c,pts,col){c.fillStyle=col;c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();c.fill()}
function diamond(c,x,y,s,col){poly(c,[[x,y-s],[x+s*.65,y],[x,y+s],[x-s*.65,y]],col)}
function crown(c,x,y,s,col){
// Individual stepped leaf clusters leave narrow sky gaps instead of solid canopy slabs.
const cells=[[-.48,.12,.26,.15],[-.29,-.02,.3,.19],[-.04,-.1,.26,.18],[.19,.01,.29,.17],[-.4,.28,.32,.17],[-.12,.15,.31,.22],[.24,.23,.27,.18],[-.21,.39,.23,.1],[.07,.36,.22,.15]];
for(let i=0;i<cells.length;i++){let [dx,dy,ww,hh]=cells[i];rect(c,x+dx*s,y+dy*s,Math.ceil(ww*s),Math.ceil(hh*s),col);}
c.save();c.globalAlpha=.22;for(let i=0;i<7;i++){let xx=x-s*.4+noise(i+x)*s*.8,yy=y+noise(i+x+8)*s*.42;rect(c,xx,yy,3+noise(i)*8,2,'#75a486')}c.restore();
}
function tree(c,x,base,s,tint,leaf){rect(c,x,base-s,12+s*.045,s,tint);poly(c,[[x+7,base-s*.55],[x-s*.24,base-s*.78],[x-s*.31,base-s*.78],[x+7,base-s*.4]],tint);poly(c,[[x+10,base-s*.72],[x+s*.26,base-s*.9],[x+s*.3,base-s*.9],[x+18,base-s*.58]],tint);crown(c,x,base-s-24,s*.34,leaf);crown(c,x-s*.26,base-s*.79,s*.26,leaf);crown(c,x+s*.24,base-s*.88,s*.25,leaf)}
function fern(c,x,y,s,flip=1){rect(c,x,y-s,2,s,'#478777');for(let i=0;i<5;i++){let yy=y-i*s/5;rect(c,x-i*2*flip,yy-3,Math.max(3,(5-i)*3),2,i%2?'#5f9b7f':'#3b7868')}}
function cat(c,p,t){let x=Math.round(p.x),y=Math.round(p.y),f=p.face||1,run=Math.abs(p.vx||0)>10,bob=run?Math.round(Math.sin(t*15))*1:0; c.save();c.translate(x+14,y+15+bob);c.scale(f,1);if((p.invuln||0)>0&&Math.floor(t*15)%2)c.globalAlpha=.55;
// Segmented upturned tail and sleek dark body.
let sway=Math.round(Math.sin(t*5)*2);rect(c,-23,2,12,5,'#06141e');rect(c,-28,-4+sway,6,10,'#06141e');rect(c,-30,-11+sway,5,9,'#06141e');rect(c,-29,-13+sway,4,5,'#213844');
rect(c,-12,-5,22,16,'#07151e');rect(c,-10,6,19,6,'#0a1a24');let a=run?Math.sin(t*19)*3:0;rect(c,-10+a,10,5,5,'#08151d');rect(c,5-a,9,5,6,'#08151d');rect(c,-9,-15,20,17,'#0b1b25');poly(c,[[-10,-10],[-11,-23],[-1,-14]],'#0b1b25');poly(c,[[3,-14],[11,-23],[12,-7]],'#0b1b25');rect(c,-8,-19,2,5,'#47706e');rect(c,8,-19,2,5,'#47706e');rect(c,-7,-9,6,4,C.cyan);rect(c,4,-9,6,4,C.cyan);rect(c,-3,-9,2,4,'#153c42');rect(c,6,-9,2,4,'#153c42');rect(c,1,-2,2,2,'#88b5af');rect(c,-8,0,4,1,'#3d5d66');rect(c,7,0,5,1,'#3d5d66');rect(c,-8,1,15,3,'#07151e');
if((p.attackUntil||0)>t){c.strokeStyle='#d1f9d2';c.lineWidth=3;c.beginPath();c.arc(12,-2,23,-1.1,1.2);c.stroke();}c.restore()}
function spirit(c,e,t){let x=e.x,y=e.y,w=e.w||26,h=e.h||30,boss=e.type==='boss';if(e.type==='wisp'){let b=Math.sin(t*4+x)*4;c.save();c.translate(x+w/2,y+h/2+b);let glow=c.createRadialGradient(0,0,1,0,0,28);glow.addColorStop(0,'rgba(248,201,118,.3)');glow.addColorStop(1,'rgba(248,201,118,0)');c.fillStyle=glow;c.fillRect(-28,-28,56,56);c.globalAlpha=.13;diamond(c,0,0,27,'#f8c976');c.globalAlpha=1;diamond(c,0,0,13,'#9e6f42');diamond(c,0,-1,8,'#e4ba75');rect(c,-5,-3,3,3,'#fff3b8');rect(c,3,-3,3,3,'#fff3b8');rect(c,-3,9,6,4,'#684a39');c.restore()}else{c.save();c.translate(x+w/2,y+h);let s=(e.h||34)/56;c.scale(s,s);let walk=Math.sin(t*4+x)*1.5;rect(c,-14, -10,10,10,'#244a49');rect(c,5,-10,10,10,'#244a49');rect(c,-18,-36,36,27,'#325856');rect(c,-22,-33,6,19,'#224647');rect(c,17,-32,7,20,'#234849');rect(c,-14,-55,28,24,'#527873');rect(c,-17,-49,33,12,'#527873');rect(c,-12,-55,24,3,'#7da08d');rect(c,-10,-45,7,4,boss?'#f2cc84':C.cyan);rect(c,4,-45,7,4,boss?'#f2cc84':C.cyan);rect(c,-4,-33,8,13,'#162f35');diamond(c,0,-25,6,boss?'#f2cd80':'#92dec5');rect(c,-16,-35,32,3,'#1f4042');rect(c,-13,-18,8,3,'#658b74');rect(c,6,-15,7,3,'#577d6d');poly(c,[[-11,-54],[-19,-66],[-19,-79],[-15,-79],[-14,-68],[-5,-57]],'#436f5d');poly(c,[[7,-55],[17,-68],[17,-80],[21,-80],[21,-66],[13,-53]],'#436f5d');rect(c,-26,-71,9,4,'#58886b');rect(c,20,-73,10,4,'#58886b');crown(c,-20,-82,13,'#6b946c');crown(c,24,-80,13,'#73966c');if(boss){rect(c,-27,-32,7,21,'#496f64');rect(c,22,-31,7,22,'#496f64');rect(c,-21,-36,8,5,'#90aa7c');rect(c,15,-35,9,5,'#90aa7c');}c.restore()}
if(e.hp<e.maxHp&&e.hp>0){let ww=boss?90:32;rect(c,x+(w-ww)/2,y-12,ww,3,'#193137');rect(c,x+(w-ww)/2,y-12,ww*e.hp/e.maxHp,3,boss?'#edc078':'#9ee0bc')}}
function gate(c,t,open){let x=3440,y=440;rect(c,x-35,y-95,12,95,'#315453');rect(c,x+35,y-95,12,95,'#315453');rect(c,x-26,y-116,64,16,'#456762');rect(c,x-36,y-101,13,9,'#658779');rect(c,x+35,y-101,13,9,'#658779');rect(c,x-32,y-95,3,87,'#719287');rect(c,x+37,y-95,3,87,'#719287');for(let i=0;i<6;i++){rect(c,x-33,y-84+i*13,6,2,open?'#a9edce':'#68847a');rect(c,x+38,y-84+i*13,6,2,open?'#a9edce':'#68847a')}
if(open){c.save();c.globalAlpha=.17+.04*Math.sin(t*3);rect(c,x-23,y-99,57,99,'#8bf7d6');c.globalAlpha=.6;for(let i=0;i<9;i++){let yy=y-((t*21+i*13)%97);rect(c,x-18+noise(i)*43,yy,2,6,'#baffea')}c.restore();}else{rect(c,x-17,y-99,42,99,'#152e33');for(let i=0;i<4;i++)rect(c,x-15,y-80+i*19,38,2,'#2d4c4c')}
diamond(c,x+5,y-110,7,open?'#c5ffcf':'#a1b99b');rect(c,x-44,y-5,100,7,'#628373');rect(c,x-49,y+2,110,7,'#3b5b52')}
export function render(ctx,g,options={}){const c=ctx,W=options.width||960,H=options.height||540,cam=options.camera||0,t=g.time||0;c.save();c.clearRect(0,0,W,H);rect(c,0,0,W,H,C.sky);
// Distant luminous atmosphere, stepped mountain ridges, and parallax silhouettes.
let sky=c.createLinearGradient(0,0,0,440);sky.addColorStop(0,'#0b1e29');sky.addColorStop(.65,'#204746');sky.addColorStop(1,'#315a50');c.fillStyle=sky;c.fillRect(0,0,W,H);
let moonX=730-cam*.035;c.fillStyle='#b7c5a3';c.fillRect(moonX,57,27,31);c.fillRect(moonX-4,63,35,18);rect(c,moonX+7,57,20,5,'#95ae95');rect(c,moonX+18,75,9,8,'#99b09a');for(let i=0;i<44;i++){let sx=(noise(i)*1200-cam*.05+1200)%1200,sy=20+noise(i+80)*200;rect(c,sx,sy,i%7===0?2:1,1,'#739996')}
for(let layer=0;layer<3;layer++){let col=['#1c3b41','#1a4143','#1d4a46'][layer],factor=.07+layer*.07;let pts=[[-30,H]];for(let i=-1;i<15;i++){let xx=i*100-(cam*factor%100),yy=210+layer*43-noise(i+Math.floor(cam*factor/100)+layer*20)*75;pts.push([xx,yy],[xx+45,yy],[xx+45,yy+18])}pts.push([W+100,H]);poly(c,pts,col)}
for(let layer=0;layer<2;layer++){let factor=.22+layer*.16,step=layer?150:105;for(let i=Math.floor(cam*factor/step)-2;i<Math.floor((cam*factor+W)/step)+2;i++){let x=i*step-cam*factor+noise(i+99)*50;tree(c,x,465,135+noise(i+7)*140,layer?'#163c3c':'#1b4442',layer?'#1c4942':'#245148')}}
// Narrow moonlit shafts fall through gaps in the canopy.
c.save();c.globalAlpha=.045;poly(c,[[moonX-10,81],[moonX+12,81],[moonX-90,435],[moonX-210,435]],'#c7e9be');c.globalAlpha=.025;poly(c,[[moonX+15,90],[moonX+30,90],[moonX+15,424],[moonX-58,424]],'#dcf7c6');c.restore();
c.save();c.translate(-Math.round(cam),0);
// Broad ancient trunks and canopy around the playable plane.
for(let i=Math.floor(cam/480)-1;i<Math.floor((cam+W)/480)+2;i++){let x=i*480+210;rect(c,x,0,28,422,'#153935');rect(c,x+6,0,5,416,'#1d453d');poly(c,[[x,334],[x-40,427],[x+59,427],[x+28,332]],'#153935');poly(c,[[x+4,127],[x-57,81],[x-82,80],[x,150]],'#153935');crown(c,x-15,-10,100,'#153c36');crown(c,x-62,16,65,'#153c36');for(let j=0;j<3;j++){let vx=x-45+j*35,len=55+noise(i+j)*80;rect(c,vx,39,2,len,'#315c4b');for(let k=0;k<4;k++)rect(c,vx+(k%2?-4:1),65+k*18,5,3,'#48785c')}}
// Still, reflective stream.
rect(c,1000,458,260,82,'#123d45');for(let i=0;i<24;i++){let xx=1004+noise(i+3)*243,yy=463+noise(i+88)*75;rect(c,xx+Math.sin(t+i)*3,yy,8+noise(i)*25,1,i%3?'#2f6969':'#72aa9e')}for(let i=0;i<6;i++)rect(c,1030+i*40,473+(i%2)*16,25,2,'#24585b');
for(const p of g.platforms||[]){if(p.x+p.w<cam-50||p.x>cam+W+50)continue;if(p.type==='ice'){rect(c,p.x,p.y,p.w,p.h||12,'#83d4d8');rect(c,p.x,p.y,p.w,3,'#d6fcf2');for(let i=0;i<p.w;i+=16){rect(c,p.x+i,p.y+5,9,2,'#b5eaf0');rect(c,p.x+i+6,p.y+10,3,5,'#77b5c6')}}else if(p.type==='branch'||p.type==='platform'){rect(c,p.x,p.y+4,p.w,p.h||12,'#3b5446');rect(c,p.x,p.y,p.w,5,'#7e9b65');rect(c,p.x+4,p.y+6,p.w-8,3,'#667653');for(let i=0;i<p.w;i+=24)rect(c,p.x+i,p.y-3,12,3,'#527d58');poly(c,[[p.x+8,p.y+12],[p.x+25,p.y+25],[p.x+35,p.y+12]],'#314d40')}else{rect(c,p.x,p.y,p.w,H-p.y,'#213f38');rect(c,p.x,p.y,p.w,5,'#88aa70');rect(c,p.x,p.y+5,p.w,8,'#567a50');rect(c,p.x,p.y+13,p.w,11,'#324d37');for(let i=Math.floor(p.x/19)*19;i<p.x+p.w;i+=19){if(i<p.x)continue;let n=noise(i);rect(c,i,p.y-3,8+Math.floor(n*10),4,'#6c9562');rect(c,i+3,p.y+18,6,10+Math.floor(n*20),'#304937');if(n>.4)rect(c,i+4,p.y+47+n*25,12,5,'#315047')}}}
// Hand-built ground dressing is deterministic and independent of frame rate.
for(let i=Math.floor(cam/29)-2;i<Math.floor((cam+W)/29)+2;i++){let x=i*29,n=noise(i+251);if(x>995&&x<1265)continue;if(n>.5)fern(c,x,440,12+n*15);else if(n>.3){rect(c,x,432,12,8,'#49645b');rect(c,x+3,429,7,3,'#6c8470')}else if(n<.13){rect(c,x+3,432,3,8,'#9aae86');rect(c,x,429,10,4,'#95c3a0');rect(c,x+1,428,8,2,'#c0ddae')}if(i%7===0){rect(c,x+8,438,30,2,'#b2be7c');rect(c,x+12,435,3,4,'#95ae68')}}
for(const p of g.pickups||[]){if(p.collected)continue;let xx=p.x+(p.w||0)/2,yy=p.y+(p.h||0)/2+Math.sin(t*2+p.x)*3;let glow=c.createRadialGradient(xx,yy,2,xx,yy,26);glow.addColorStop(0,'rgba(142,241,223,.27)');glow.addColorStop(1,'rgba(142,241,223,0)');c.fillStyle=glow;c.fillRect(xx-26,yy-26,52,52);c.globalAlpha=.15;diamond(c,xx,yy,18,C.cyan);c.globalAlpha=1;diamond(c,xx,yy,9,'#66cbbf');diamond(c,xx-1,yy-2,5,'#ceffe5');rect(c,xx-1,yy+13,2,2,'#83c8b3')}
// A small stone spring marks the midpoint checkpoint.
rect(c,1720,430,49,10,'#486a60');rect(c,1725,425,39,5,'#81a18a');rect(c,1730,428,28,4,g.checkpointTaken?'#9bedcf':'#527d79');rect(c,1740,399,7,26,'#426258');diamond(c,1743,397,8,g.checkpointTaken?'#b6ffe0':'#6ea394');
gate(c,t,(g.bossDefeated&&g.shards>=3)||g.status==='won');
for(const e of g.enemies||[])if(e.hp>0&&!e.dead){spirit(c,e,t);if((e.frozenUntil||0)>t){
const ex=e.x,ey=e.y,ew=e.w||34,eh=e.h||34;c.save();c.globalAlpha=.23;rect(c,ex-3,ey-3,ew+6,eh+3,'#a6eaff');c.globalAlpha=.9;rect(c,ex-3,ey-3,ew+6,2,'#dcffff');rect(c,ex-3,ey-3,2,eh,'#9de7ee');rect(c,ex+ew+1,ey,2,eh,'#9de7ee');for(let k=0;k<3;k++){const xx=ex+ew*(k+1)/4;poly(c,[[xx-3,ey+eh],[xx,ey+eh-9],[xx+4,ey+eh]],'#b3f7f5')}c.restore();
}}
for(const p of g.projectiles||[]){let col=p.type==='ice'?'#bbfaff':p.type==='hostile'?'#ecae73':'#c3e4d2';let dir=(p.vx||1)>0?1:-1;rect(c,p.x-dir*16,p.y-1,14,2,p.type==='hostile'?'#825e49':'#527d78');diamond(c,p.x,p.y,p.type==='ice'?6:4,col)}
if(g.player)cat(c,g.player,t);
for(const p of g.particles||[]){if(!Number.isFinite(p.x)||!Number.isFinite(p.y))continue;c.globalAlpha=p.alpha??Math.min(1,Math.max(0,(p.life??1)));rect(c,p.x,p.y,p.size||3,p.size||3,p.color||C.cyan)}c.globalAlpha=1;
if((g.iceBridgeUntil||0)>t){const secs=Math.ceil(g.iceBridgeUntil-t);c.font='bold 11px system-ui, sans-serif';c.textAlign='center';c.fillStyle=secs<=3?'#f4d394':'#c1f5ec';c.fillText('冰桥 · '+secs+' 秒',1130,426);}
// Environmental labels stay quiet, leaving gameplay and UI in focus.
c.font='11px system-ui, sans-serif';c.textAlign='center';c.fillStyle='#92b6a1';for(const [x,txt]of [[190,'出 生 之 林'],[1125,'镜 水 溪'],[2360,'古 树 庭'],[3445,'灵 境 之 门']]){if(x>cam-80&&x<cam+W+80){c.fillText(txt,x,398);rect(c,x-15,407,30,1,'#587b68')}}
for(let i=Math.floor(cam/60);i<Math.floor((cam+W)/60)+1;i++){let xx=i*60+noise(i)*30,yy=255+noise(i+180)*150+Math.sin(t+i)*5;c.globalAlpha=.3+.4*(.5+.5*Math.sin(t*1.4+i));rect(c,xx,yy,2,2,'#d6efaa')}c.globalAlpha=1;c.restore();
// Dark near-ground leaves frame the scene, while center sightlines remain open.
for(let i=0;i<12;i++){let xx=(i*97-cam*.7%97),yy=523+noise(i)*14;fern(c,xx,yy,23+noise(i+2)*15);rect(c,xx-8,yy,20,18,'#15342f')}
let vig=c.createLinearGradient(0,0,0,H);vig.addColorStop(0,'rgba(3,15,23,.22)');vig.addColorStop(.3,'rgba(3,15,23,0)');vig.addColorStop(.8,'rgba(3,15,23,0)');vig.addColorStop(1,'rgba(3,15,23,.25)');c.fillStyle=vig;c.fillRect(0,0,W,H);c.restore()}
